<script setup>
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue';

import { apiClient, authSession } from '../lib/auth/index.js';
import { workspaceModules } from '../lib/workspace/index.js';
import ConnectorAdminPanel from '../components/admin/ConnectorAdminPanel.vue';
import RedirectUriListInput from '../components/admin/RedirectUriListInput.vue';

const emptyWorkspace = () => ({ applications: [], deliveries: [], health: [], subscriptions: [] });
const workspace = ref(emptyWorkspace()); const loading = ref(true); const errorMessage = ref(''); const activeTab = ref('oauth applications'); const query = ref(''); const status = ref(''); const fromDate = ref(''); const sortDirection = ref('desc'); const page = ref(1); const pageSize = 25; const dialog = ref(null); const editor = reactive({ kind: '', values: {} }); const oneTimeSecret = ref(''); const token = computed(() => authSession.state.token);
const projects = ref([]); const projectsFailed = ref(false); const redirectInput = ref(null); const projectNames = computed(() => new Map(projects.value.map((item) => [item.id, item.name])));
// Projects the editor can offer: every tenant project plus any allowlisted ID the list does not include.
const projectChoices = computed(() => [...projects.value, ...(editor.values.projectIds ?? []).filter((id) => !projectNames.value.has(id)).map((id) => ({ id, name: id }))]);
const healthMap = computed(() => new Map(workspace.value.health.map((item) => [item.subscriptionId, item])));
const subscriptionMap = computed(() => new Map(workspace.value.subscriptions.map((item) => [item.id, item])));
const source = computed(() => activeTab.value === 'oauth applications' ? workspace.value.applications : activeTab.value === 'webhooks' ? workspace.value.subscriptions : activeTab.value === 'deliveries' ? workspace.value.deliveries : []);
const filtered = computed(() => {
  const needle = query.value.trim().toLowerCase(); const minimum = fromDate.value ? Date.parse(fromDate.value) : 0;
  return [...source.value].filter((item) => {
    if (needle && !JSON.stringify(item).toLowerCase().includes(needle)) return false;
    if (status.value && String(item.status ?? (item.enabled ? 'enabled' : 'disabled')) !== status.value) return false;
    if (minimum && Date.parse(item.createdAt ?? 0) < minimum) return false;
    return true;
  }).sort((left, right) => sortDirection.value === 'asc' ? String(left.createdAt ?? left.name).localeCompare(String(right.createdAt ?? right.name)) : String(right.createdAt ?? right.name).localeCompare(String(left.createdAt ?? left.name)));
});
const pageCount = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize))); const visible = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize));
watch([query, status, fromDate], () => { page.value = 1; });
watch(activeTab, () => { page.value = 1; status.value = ''; fromDate.value = ''; });
// Engagements can be allowlisted too, while the Consulting module is on: invoice-gen links SOWs to them.
function engagementChoices(list) { return (list?.engagements ?? []).filter((item) => item.status !== 'lost').map((item) => ({ id: item.id, name: `${item.name} (engagement)` })); }
async function load() { loading.value = true; errorMessage.value = ''; try { const [result, projectList, engagementList] = await Promise.all([apiClient.getIntegrationWorkspace({ limit: 200 }, token.value), apiClient.getProjects(token.value).then((value) => { projectsFailed.value = false; return value; }, () => { projectsFailed.value = true; return { projects: [] }; }), (workspaceModules.state.consulting ? apiClient.passive.listEngagements(token.value).catch(() => ({ engagements: [] })) : { engagements: [] })]); workspace.value = result; projects.value = [...(projectList?.projects ?? []), ...engagementChoices(engagementList)].sort((left, right) => String(left.name).localeCompare(String(right.name))); } catch (error) { errorMessage.value = error.message ?? 'Unable to load integration controls.'; } finally { loading.value = false; } }
function csv(value) { return String(value ?? '').split(',').map((item) => item.trim()).filter(Boolean); }
function projectLabels(item) { return item.projectIds.map((id) => projectNames.value.get(id) ?? id).join(', '); }
async function openEditor(kind) { editor.kind = kind; oneTimeSecret.value = ''; errorMessage.value = ''; editor.values = kind === 'oauth' ? { name: '', projectIds: [], redirectUris: [], scopesText: 'projects.read' } : { description: '', eventTypesText: 'governance.changed', name: '', url: 'https://' }; await nextTick(); dialog.value?.showModal(); }
async function openApplicationEditor(item) { editor.kind = 'application'; oneTimeSecret.value = ''; errorMessage.value = ''; editor.values = { application: item, projectIds: [...item.projectIds], redirectUris: [...(item.redirectUris ?? [])] }; await nextTick(); dialog.value?.showModal(); }
function closeEditor() { dialog.value?.close(); }
const projectEditor = computed(() => ['oauth', 'application'].includes(editor.kind));
async function saveEditor() { errorMessage.value = ''; if (projectEditor.value && projectsFailed.value) return; if (projectEditor.value && redirectInput.value && !redirectInput.value.commitPending()) return; try { const value = editor.values; if (editor.kind === 'application') { await apiClient.updateOAuthApplication(value.application.id, { projectIds: value.projectIds, redirectUris: value.redirectUris, expectedVersion: value.application.version }, token.value); await load(); closeEditor(); return; } const result = editor.kind === 'oauth' ? await apiClient.createOAuthApplication({ name: value.name, projectIds: value.projectIds, redirectUris: value.redirectUris, scopes: csv(value.scopesText) }, token.value) : await apiClient.createWebhookSubscription({ description: value.description, eventTypes: csv(value.eventTypesText), name: value.name, url: value.url }, token.value); oneTimeSecret.value = result.clientSecret ?? result.signingSecret ?? ''; await load(); if (!oneTimeSecret.value) closeEditor(); } catch (error) { errorMessage.value = error.message ?? 'Unable to save integration control.'; } }
async function rotateApplication(item) { try { if (item.clientId.startsWith('odin_mcp_client_')) { await apiClient.revokeMcpClient(item.clientId, token.value); await load(); return; } const result = await apiClient.rotateOAuthApplicationCredential(item.id, item.version, token.value); oneTimeSecret.value = result.clientSecret; editor.kind = 'secret'; await load(); await nextTick(); dialog.value?.showModal(); } catch (error) { errorMessage.value = error.message; } }
async function rotateWebhook(item) { try { const result = await apiClient.rotateWebhookSigningSecret(item.id, item.version, token.value); oneTimeSecret.value = result.signingSecret; editor.kind = 'secret'; await load(); await nextTick(); dialog.value?.showModal(); } catch (error) { errorMessage.value = error.message; } }
async function toggleApplication(item) { try { await apiClient.updateOAuthApplication(item.id, { enabled: !item.enabled, expectedVersion: item.version }, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
async function toggleWebhook(item) { try { await apiClient.updateWebhookSubscription(item.id, { enabled: !item.enabled, expectedVersion: item.version }, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
async function replay(item) { try { await apiClient.replayWebhookDelivery(item.id, item.version, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
function dateTime(value) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
onMounted(load);
</script>

<template>
  <main class="integration-page"><header><div><h1>API &amp; integrations</h1><p>OAuth clients, signed event subscriptions, delivery health, retries, and dead-letter replay.</p></div><button class="btn btn-sm btn-outline-secondary" type="button" @click="load"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i> Refresh</button></header>
    <div v-if="errorMessage" class="alert alert-danger" role="alert">{{ errorMessage }}</div>
    <nav aria-label="Integration control sections"><button v-for="tab in ['oauth applications','webhooks','deliveries','connectors']" :key="tab" :class="{ active: activeTab === tab }" type="button" @click="activeTab = tab">{{ tab }}</button></nav>
    <div v-if="activeTab !== 'connectors'" class="toolbar"><label>Search<input v-model="query" type="search" placeholder="Name, scope, event, or ID" /></label><label v-if="activeTab === 'deliveries'">Status<select v-model="status"><option value="">All</option><option value="pending">Pending</option><option value="processing">Processing</option><option value="delivered">Delivered</option><option value="dead">Dead</option></select></label><label v-if="activeTab === 'deliveries'">Created after<input v-model="fromDate" type="date" /></label><label>Sort<select v-model="sortDirection"><option value="desc">Newest first</option><option value="asc">Oldest first</option></select></label></div>
    <p v-if="loading" role="status">Loading integration controls…</p>
    <template v-else>
      <section v-if="activeTab === 'oauth applications'" aria-labelledby="oauth-applications-title"><div class="section-heading"><h2 id="oauth-applications-title">OAuth applications</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('oauth')"><i class="bi bi-plus-lg" aria-hidden="true"></i> Add application</button></div><div class="table-responsive" role="region" aria-label="OAuth applications table" tabindex="0"><table><thead><tr><th>Name</th><th>Client ID</th><th>Scopes</th><th>Projects</th><th>Redirect URIs</th><th>Status</th><th>Last used</th><th>Actions</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td>{{ item.name }}</td><td><code>{{ item.clientId }}</code></td><td>{{ item.scopes.join(', ') }}</td><td>{{ projectLabels(item) || (item.clientId.startsWith('odin_mcp_client_') ? 'All accessible projects' : 'None') }}</td><td><ul v-if="item.redirectUris?.length" class="uri-list"><li v-for="uri in item.redirectUris" :key="uri"><code>{{ uri }}</code></li></ul><template v-else>Not set</template></td><td><span class="status">{{ item.enabled ? 'enabled' : 'disabled' }}</span></td><td>{{ dateTime(item.lastUsedAt) }}</td><td><div class="actions"><button v-if="!item.clientId.startsWith('odin_mcp_client_')" class="btn btn-sm btn-outline-secondary" type="button" :aria-label="`Edit ${item.name}`" @click="openApplicationEditor(item)">Edit</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="rotateApplication(item)">{{ item.clientId.startsWith('odin_mcp_client_') ? 'Revoke sessions' : 'Rotate' }}</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="toggleApplication(item)">{{ item.enabled ? 'Disable' : 'Enable' }}</button></div></td></tr></tbody></table></div><p v-if="!visible.length" class="empty">No OAuth applications match these filters.</p></section>
      <section v-if="activeTab === 'webhooks'" aria-labelledby="webhooks-title"><div class="section-heading"><h2 id="webhooks-title">Webhook subscriptions</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('webhook')"><i class="bi bi-plus-lg" aria-hidden="true"></i> Add webhook</button></div><div class="table-responsive" role="region" aria-label="Webhook subscriptions table" tabindex="0"><table><thead><tr><th>Name</th><th>Endpoint</th><th>Events</th><th>Health</th><th>Last delivery</th><th>Actions</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td>{{ item.name }}</td><td><code>{{ item.url }}</code></td><td>{{ item.eventTypes.join(', ') }}</td><td><span class="status">{{ healthMap.get(item.id)?.status ?? (item.enabled ? 'healthy' : 'disabled') }}</span></td><td>{{ dateTime(item.lastDeliveredAt) }}</td><td><div class="actions"><button class="btn btn-sm btn-outline-secondary" type="button" @click="rotateWebhook(item)">Rotate secret</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="toggleWebhook(item)">{{ item.enabled ? 'Disable' : 'Enable' }}</button></div></td></tr></tbody></table></div><p v-if="!visible.length" class="empty">No webhook subscriptions match these filters.</p></section>
      <section v-if="activeTab === 'deliveries'" aria-labelledby="deliveries-title"><div class="section-heading"><h2 id="deliveries-title">Delivery attempts</h2><span>{{ filtered.length }} results</span></div><div class="table-responsive" role="region" aria-label="Webhook delivery attempts table" tabindex="0"><table><thead><tr><th>Event</th><th>Subscription</th><th>Status</th><th>Attempts</th><th>HTTP</th><th>Updated</th><th>Action</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td><code>{{ item.eventType }}</code><small>{{ item.eventId }}</small></td><td>{{ subscriptionMap.get(item.subscriptionId)?.name ?? item.subscriptionId }}</td><td><span class="status">{{ item.status }}</span></td><td>{{ item.attempts }}</td><td>{{ item.responseCode ?? '—' }}</td><td>{{ dateTime(item.updatedAt) }}</td><td><button v-if="['dead','delivered'].includes(item.status)" class="btn btn-sm btn-outline-secondary" type="button" @click="replay(item)">Replay</button></td></tr></tbody></table></div><p v-if="!visible.length" class="empty">No delivery attempts match these filters.</p></section>
      <ConnectorAdminPanel v-if="activeTab === 'connectors'" />
      <footer v-if="activeTab !== 'connectors'" class="pagination"><button class="btn btn-sm btn-outline-secondary" type="button" :disabled="page <= 1" @click="page -= 1">Previous</button><span>Page {{ page }} of {{ pageCount }}</span><button class="btn btn-sm btn-outline-secondary" type="button" :disabled="page >= pageCount" @click="page += 1">Next</button></footer>
    </template>
    <dialog ref="dialog" aria-labelledby="integration-editor-title" @cancel.prevent="closeEditor"><form @submit.prevent="saveEditor"><header><h2 id="integration-editor-title">{{ oneTimeSecret ? 'Copy secret now' : editor.kind === 'oauth' ? 'Add OAuth application' : editor.kind === 'application' ? `Edit ${editor.values.application.name}` : 'Add webhook subscription' }}</h2><button class="icon-button" aria-label="Close integration editor" type="button" @click="closeEditor"><i class="bi bi-x-lg"></i></button></header>
      <div v-if="oneTimeSecret" class="secret"><strong>Shown once</strong><code>{{ oneTimeSecret }}</code><p>Store this value in an approved secrets manager. It cannot be retrieved again.</p></div>
      <template v-else-if="editor.kind === 'oauth'"><label>Name<input v-model="editor.values.name" required /></label><label>Scopes <small>Comma separated: projects.read, projects.write, audit.read, billing.read, billing.write</small><input v-model="editor.values.scopesText" required /></label><p v-if="projectsFailed" class="alert alert-warning" role="alert">Projects could not be loaded, so the allowlist cannot be changed. Refresh and try again.</p><fieldset v-else class="project-picker"><legend>Projects</legend><label v-for="project in projectChoices" :key="project.id" class="project-choice"><input v-model="editor.values.projectIds" type="checkbox" :value="project.id" /><span>{{ project.name }}<small v-if="project.name !== project.id">{{ project.id }}</small></span></label><p v-if="!projectChoices.length" class="empty">No projects are available.</p></fieldset><RedirectUriListInput ref="redirectInput" v-model="editor.values.redirectUris" /></template>
      <template v-else-if="editor.kind === 'application'"><p>The application can act only for the projects selected here. Removing a project stops the application's access to it.</p><p v-if="projectsFailed" class="alert alert-warning" role="alert">Projects could not be loaded, so the allowlist cannot be changed. Refresh and try again.</p><fieldset v-else class="project-picker"><legend>Projects</legend><label v-for="project in projectChoices" :key="project.id" class="project-choice"><input v-model="editor.values.projectIds" type="checkbox" :value="project.id" /><span>{{ project.name }}<small v-if="project.name !== project.id">{{ project.id }}</small></span></label><p v-if="!projectChoices.length" class="empty">No projects are available.</p></fieldset><RedirectUriListInput ref="redirectInput" v-model="editor.values.redirectUris" /></template>
      <template v-else><label>Name<input v-model="editor.values.name" required /></label><label>Description<textarea v-model="editor.values.description"></textarea></label><label>HTTPS endpoint<input v-model="editor.values.url" type="url" required /></label><label>Event types <small>Comma separated</small><textarea v-model="editor.values.eventTypesText" required></textarea></label></template>
      <p v-if="errorMessage && !oneTimeSecret" class="alert alert-danger" role="alert">{{ errorMessage }}</p>
      <footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="closeEditor">Close</button><button v-if="!oneTimeSecret && editor.kind !== 'secret'" class="btn btn-sm btn-primary" type="submit" :disabled="projectEditor && projectsFailed">Save</button></footer>
    </form></dialog>
  </main>
</template>

<style scoped>
.integration-page{padding:1rem;min-height:100%;font-size:.875rem}.integration-page>header,.section-heading,.actions,dialog header,dialog footer,.pagination{display:flex;align-items:center;justify-content:space-between;gap:.75rem}.integration-page>header{margin-bottom:.75rem}.integration-page h1{font-size:1.375rem;margin:0;line-height:1.2}.integration-page h2{font-size:1.125rem;margin:0}.integration-page p{margin:.25rem 0;color:var(--bs-secondary-color)}nav{display:flex;gap:.25rem;overflow:auto;border-bottom:1px solid var(--bs-border-color);margin-bottom:.75rem}nav button{min-height:2.75rem;padding:.5rem .75rem;border:0;background:transparent;color:var(--bs-secondary-color);text-transform:capitalize;white-space:nowrap}nav button.active{color:var(--bs-body-color);box-shadow:inset 0 -2px var(--bs-primary)}.toolbar{display:flex;align-items:end;gap:.5rem;flex-wrap:wrap;margin-bottom:.75rem}.toolbar label{min-width:10rem}.toolbar label:first-child{flex:1;min-width:14rem}section{border:1px solid var(--bs-border-color);border-radius:.5rem;padding:.75rem}.section-heading{margin-bottom:.75rem}.table-responsive{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.5rem .75rem;border-bottom:1px solid var(--bs-border-color);vertical-align:middle}th{font-weight:600;white-space:nowrap}td code{overflow-wrap:anywhere}td small{display:block;color:var(--bs-secondary-color);font-size:.75rem;margin-top:.25rem}.status{display:inline-flex;padding:.2rem .5rem;border:1px solid var(--bs-border-color);border-radius:999px}.actions{justify-content:flex-start}.empty{text-align:center;padding:1rem}.pagination{justify-content:flex-end;margin-top:.75rem}.toolbar label,dialog label{display:grid;gap:.25rem;font-weight:600}.toolbar input,.toolbar select,dialog input,dialog textarea{min-height:2.75rem;border:1px solid var(--bs-border-color);border-radius:.375rem;padding:.5rem;background:var(--bs-body-bg);color:var(--bs-body-color)}dialog{width:min(38rem,calc(100vw - 2rem));border:1px solid var(--bs-border-color);border-radius:.625rem;padding:0;background:var(--bs-body-bg);color:var(--bs-body-color)}dialog::backdrop{background:rgba(0,0,0,.55)}dialog form{padding:1rem;display:grid;gap:.75rem}dialog header{border-bottom:1px solid var(--bs-border-color);padding-bottom:.75rem}dialog footer{justify-content:flex-end;border-top:1px solid var(--bs-border-color);padding-top:.75rem}.icon-button{width:2.75rem;height:2.75rem;border:0;background:transparent;color:inherit}.secret{display:grid;gap:.5rem}.project-picker{display:grid;gap:.25rem;max-height:18rem;overflow:auto;margin:0;padding:.5rem .75rem;border:1px solid var(--bs-border-color);border-radius:.375rem}.project-picker legend{float:none;width:auto;margin:0;padding:0 .25rem;font-size:.875rem;font-weight:600}dialog .project-choice{display:flex;align-items:center;gap:.5rem;min-height:2.75rem;font-weight:400}.project-choice input{width:1.125rem;height:1.125rem;min-height:0;flex-shrink:0}.project-choice small{display:block;color:var(--bs-secondary-color);font-family:var(--bs-font-monospace);font-size:.75rem;overflow-wrap:anywhere}.uri-list{margin:0;padding:0;list-style:none}.uri-list code{font-size:.75rem;color:var(--bs-body-color)}.secret code{padding:.75rem;background:var(--bs-tertiary-bg);border-radius:.375rem;overflow-wrap:anywhere;user-select:all}.btn,.icon-button,nav button{min-height:2.75rem}:focus-visible{outline:3px solid color-mix(in srgb,var(--bs-primary) 65%,transparent);outline-offset:2px}@media(max-width:42rem){.integration-page{padding:.75rem}.integration-page>header{align-items:flex-start}.toolbar{display:grid;grid-template-columns:1fr 1fr}.toolbar label:first-child{grid-column:1/-1}th,td{min-width:8rem;padding:.5rem}.actions{flex-wrap:wrap}.pagination{justify-content:space-between}}
</style>
